package com.mo.economy_system.target.forge1201.network;
import com.mo.economy_system.common.network.*;import com.mo.economy_system.common.transfer.*;import com.mo.economy_system.target.forge1201.client.Forge1201ClientFileCheckClientRuntime;import java.nio.file.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
final class Forge1201CheckedFileTransferClient{private static CheckedFileTransferIncoming incoming;private static CheckedFileTransferControlResponseMessage metadata;private Forge1201CheckedFileTransferClient(){}
 static void request(CheckedFileTransferRequestMessage m){Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.getConnection()==null||!mc.player.getUUID().equals(m.targetPlayerId()))return;var e=Forge1201ClientFileCheckClientRuntime.manifest().find(new CheckedFileTransferManifestCache.Key(m.requesterPlayerId(),m.checkType(),m.fileName()),System.nanoTime());if(e.isEmpty()){Forge1201NetworkChannel.sendToServer(CheckedFileTransferOutgoing.control(m,CheckedFileTransferControl.error(CheckedFileTransferControlStatus.FAILED,"STALE_CHECK")));return;}mc.setScreen(new Consent(m,e.get(),mc.getConnection()));}
 static synchronized void control(CheckedFileTransferControlResponseMessage m){Minecraft mc=Minecraft.getInstance();if(mc.player==null||!mc.player.getUUID().equals(m.requesterPlayerId()))return;try{var c=CheckedFileTransferControlJsonCodec.decode(m.controlPayload());if(c.status()==CheckedFileTransferControlStatus.READY){clear();metadata=m;incoming=new CheckedFileTransferIncoming(c.transferId(),c.byteLength(),c.sha256(),c.totalChunks(),mc.gameDirectory.toPath().resolve("economy_system").resolve("transfer-temp"));}else if(c.status()==CheckedFileTransferControlStatus.COMPLETE&&incoming!=null){Path p=incoming.complete(c);incoming=null;metadata=null;mc.setScreen(new Result(m,p,c));}}catch(Exception e){clear();}}
 static synchronized void chunk(CheckedFileTransferChunkResponseMessage m){if(incoming==null||metadata==null)return;try{incoming.chunk(m.transferId(),m.chunkIndex(),m.totalChunks(),m.chunkData());}catch(Exception e){clear();}}private static void clear(){if(incoming!=null)try{incoming.close();}catch(Exception ignored){}incoming=null;metadata=null;}
 private static final class Consent extends Screen{final CheckedFileTransferRequestMessage r;final CheckedFileTransferManifestCache.Entry e;final Object connection;boolean done;Consent(CheckedFileTransferRequestMessage r,CheckedFileTransferManifestCache.Entry e,Object c){super(Component.translatable("screen.transfer_consent.title"));this.r=r;this.e=e;connection=c;}protected void init(){if(width<220||height<140)return;addRenderableWidget(Button.builder(Component.translatable("button.transfer.allow"),b->allow()).bounds(width/2-105,height-25,100,20).build());addRenderableWidget(Button.builder(Component.translatable("button.transfer.decline"),b->decline()).bounds(width/2+5,height-25,100,20).build());}public void render(GuiGraphics g,int x,int y,float p){renderBackground(g);super.render(g,x,y,p);g.drawCenteredString(font,title,width/2,18,0xffffff);if(height>=110){g.drawString(font,Component.translatable("screen.transfer_consent.requester",r.requesterPlayerName()),12,42,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_consent.file",r.fileName()),12,66,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_consent.size",e.size()),12,78,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_consent.hash",e.sha256()),12,90,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_consent.warning"),12,102,0xccaa66);}}boolean valid(){Minecraft m=Minecraft.getInstance();return m.getConnection()==connection&&m.player!=null&&m.player.getUUID().equals(r.targetPlayerId());}void allow(){if(done||!valid())return;done=true;Minecraft mc=Minecraft.getInstance();mc.setScreen(null);Thread t=new Thread(()->{var o=CheckedFileSnapshotter.create(mc.gameDirectory.toPath(),r.checkType(),r.fileName(),e.size(),e.sha256(),mc.gameDirectory.toPath().resolve("economy_system").resolve("transfer-temp"),System.nanoTime()+30_000_000_000L);if(!o.success()){error(o.errorCode());return;}try(var s=o.snapshot()){CheckedFileTransferOutgoing.send(r,s,this::valid,msg->{if(msg instanceof CheckedFileTransferControlRequestMessage v)Forge1201NetworkChannel.sendToServer(v);else Forge1201NetworkChannel.sendToServer((CheckedFileTransferChunkRequestMessage)msg);});}catch(Exception ex){error("SNAPSHOT_FAILED");}},"economy-file-transfer");t.setDaemon(true);t.start();}void decline(){if(done)return;done=true;error("DECLINED");Minecraft.getInstance().setScreen(null);}void error(String code){if(valid())Forge1201NetworkChannel.sendToServer(CheckedFileTransferOutgoing.control(r,CheckedFileTransferControl.error(code.equals("DECLINED")?CheckedFileTransferControlStatus.DECLINED:CheckedFileTransferControlStatus.FAILED,code)));}public void onClose(){decline();}}
 private static final class Result extends Screen{final CheckedFileTransferControlResponseMessage m;final Path temp;final CheckedFileTransferControl c;Result(CheckedFileTransferControlResponseMessage m,Path p,CheckedFileTransferControl c){super(Component.translatable("screen.transfer_result.title"));this.m=m;temp=p;this.c=c;}protected void init(){if(width<220||height<120)return;addRenderableWidget(Button.builder(Component.translatable("button.transfer.save"),b->save()).bounds(width/2-105,height-25,100,20).build());addRenderableWidget(Button.builder(Component.translatable("button.transfer.discard"),b->discard()).bounds(width/2+5,height-25,100,20).build());}public void render(GuiGraphics g,int x,int y,float p){renderBackground(g);super.render(g,x,y,p);g.drawCenteredString(font,title,width/2,18,0xffffff);if(height>=90){g.drawString(font,Component.translatable("screen.transfer_result.source",m.targetPlayerName()),12,42,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_result.file",m.fileName()),12,54,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_result.size",c.byteLength()),12,66,0xdddddd);g.drawString(font,Component.translatable("screen.transfer_result.hash",c.sha256()),12,78,0xdddddd);}}void save(){try{Path dir=Minecraft.getInstance().gameDirectory.toPath().resolve("economy_system").resolve("received-check-files").resolve(m.targetPlayerId().toString());Files.createDirectories(dir);Path target=dir.resolve(m.fileName());for(int i=1;Files.exists(target,LinkOption.NOFOLLOW_LINKS)&&i<=100;i++)target=dir.resolve(i+"-"+m.fileName());Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE);Minecraft.getInstance().setScreen(null);}catch(Exception ignored){}}void discard(){try{Files.deleteIfExists(temp);}catch(Exception ignored){}Minecraft.getInstance().setScreen(null);}public void onClose(){discard();}}
}
